import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import com.fasterxml.jackson.dataformat.yaml.YAMLMapper;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.api.extension.MockitoExtension;
import org.junit.jupiter.api.extension.MockitoJUnitRunner;
import org.mockito.Mockito;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

@ExtendWith(MockitoExtension.class)
@MockitoJUnitRunner
public class TextConversionUtilGeneratedAiTests {

    private TextConversionUtil textConversionUtil;

    @BeforeEach
    void setUp() {
        textConversionUtil = new TextConversionUtil();
    }

    @Test
    void convertJsonToYaml_validJson_returnsYamlString() {
        // GIVEN a valid JSON string
        String json = "{\"name\":\"John\", \"age\":30}";
        // WHEN the convertJsonToYaml method is called
        String yaml = textConversionUtil.convertJsonToYaml(json);
        // THEN the returned string is the YAML representation of the JSON
        assertEquals("# YAML: ---\\nname: John\\nage: 30", yaml);
    }

    @Test
    void convertJsonToXml_validJson_returnsXmlString() {
        // GIVEN a valid JSON string
        String json = "{\"name\":\"John\", \"age\":30}";
        // WHEN the convertJsonToXml method is called
        String xml = textConversionUtil.convertJsonToXml(json);
        // THEN the returned string is the XML representation of the JSON
        assertEquals("<?xml version=\"1.0\"?>\n<root><name>John</name><age>30</age></root>", xml);
    }

    @Test
    void convertJsonToYaml_invalidJson_returnsErrorString() {
        // GIVEN an invalid JSON string
        String json = "{\"name\":\"John\", \"age\":30";
        // WHEN the convertJsonToYaml method is called
        String error = textConversionUtil.convertJsonToYaml(json);
        // THEN the returned string is an error message
        assertEquals("Error converting JSON to YAML: Unexpected character at position 21", error);
    }

    @Test
    void convertJsonToXml_invalidJson_returnsErrorString() {
        // GIVEN an invalid JSON string
        String json = "{\"name\":\"John\", \"age\":30";
        // WHEN the convertJsonToXml method is called
        String error = textConversionUtil.convertJsonToXml(json);
        // THEN the returned string is an error message
        assertEquals("Error converting JSON to XML: Unexpected character at position 21", error);
    }
}

